// Trasforma gli eventi dell'app in righe per i fogli Google.
// Se imposti TOKEN, deve coincidere con il "Token" nelle impostazioni dell'app.
const TOKEN = '';

const out = [];
const lista = (a) => (a || []).join(', ');
const orig = (o) => o ? [
  o.nato && `Nato: ${o.nato}`,
  o.allevato && `Allevato: ${o.allevato}`,
  o.macellato && `Macellato: ${o.macellato}`,
  o.sezionato && `Sezionato: ${o.sezionato}`,
  o.rifOrigine && `Rif: ${o.rifOrigine}`,
].filter(Boolean).join(' | ') : '';

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  if (TOKEN && headers['x-trac-token'] !== TOKEN) {
    throw new Error('Token non valido');
  }
  for (const e of (item.json.body?.eventi || [])) {
    const d = e.dati || {};
    const base = { evento_id: e.id, tipo: e.tipo, ts: e.ts, negozio: e.negozio || '', operatore: e.operatore || '' };

    if (e.tipo === 'ricevimento') {
      out.push({ json: { foglio: 'Ricevimenti', ...base,
        lotto_id: d.id, prodotto: d.nome, gtin: d.gtin || '', fornitore: d.fornitore || '',
        lotto_fornitore: d.codiceLotto || '', scadenza: d.scadenza || '', peso_kg: d.pesoKg ?? '',
        ddt: d.ddt || '', data_arrivo: d.dataArrivo || '', temperatura: d.temperatura ?? '',
        conforme: d.conforme ? 'SI' : 'NO', stato: d.stato, allergeni: lista(d.allergeni),
        origine: orig(d.origine), codice_barre: d.codiceBarre || '', note: d.note || '' } });
    } else if (e.tipo === 'produzione') {
      out.push({ json: { foglio: 'Produzioni', ...base,
        lotto_id: d.id, prodotto: d.nome, data_produzione: d.dataProduzione, scadenza: d.scadenza,
        quantita: d.quantita, unita: d.unita, allergeni: lista(d.allergeni), origine: orig(d.origine),
        componenti: (d.componenti || []).map((c) => `${c.ingrediente}: ${c.lottoId}`).join(' | '),
        note: d.note || '' } });
      // Una riga per componente: comoda per filtrare "dove è finito il lotto X"
      for (const c of (d.componenti || [])) {
        out.push({ json: { foglio: 'Componenti', evento_id: e.id, ts: e.ts, negozio: base.negozio,
          lotto_prodotto: d.id, prodotto: d.nome, ingrediente: c.ingrediente,
          lotto_ingrediente: c.lottoId, quantita: c.quantita || '' } });
      }
    } else if (e.tipo === 'stato_lotto') {
      out.push({ json: { foglio: 'Movimenti', ...base, lotto_id: d.id, prodotto: d.nome || '',
        lotto_fornitore: d.codiceLotto || '', stato: d.stato, motivo: d.motivo || '' } });
    } else {
      out.push({ json: { foglio: 'Eventi', ...base, dati: JSON.stringify(d) } });
    }
  }
}
return out;
